svg.script:
(function () {
  var svg = document.documentElement;
  var root = document.getElementById('parallaxRoot');
  var layers = Array.prototype.slice.call(document.querySelectorAll('.layer'));
  var cx = 600, cy = 450;

  function clearHot() {
    layers.forEach(function (l) {
      l.classList.remove('is-hot', 'is-dim');
    });
  }

  layers.forEach(function (layer) {
    var hit = layer.querySelector('.hit');
    if (!hit) return;
    hit.addEventListener('mouseenter', function () {
      layers.forEach(function (l) {
        if (l === layer) {
          l.classList.add('is-hot');
          l.classList.remove('is-dim');
        } else {
          l.classList.add('is-dim');
          l.classList.remove('is-hot');
        }
      });
    });
    hit.addEventListener('mouseleave', clearHot);
  });

  svg.addEventListener('mousemove', function (e) {
    var rect = svg.getBoundingClientRect();
    var x = ((e.clientX - rect.left) / rect.width) * 1200;
    var y = ((e.clientY - rect.top) / rect.height) * 900;
    var dx = (x - cx) / cx;
    var dy = (y - cy) / cy;
    root.setAttribute(
      'transform',
      'translate(' + (dx * 14) + ',' + (dy * 10) + ') rotate(' + (dx * 1.8) + ' ' + cx + ' ' + cy + ')'
    );
  });

  svg.addEventListener('mouseleave', function () {
    root.setAttribute('transform', 'translate(0,0)');
    clearHot();
  });
})();
